/* Local, embedded JPEG textures keep both WebGL and Canvas origin-clean under file://. */
(function(root){
  'use strict';
  root.RelativityTextures=Object.freeze({
    sky: 'data:image/jpeg;base64,',
    stone:'data:image/jpeg;base64,',
    crate: 'data:image/jpeg;base64,',
    facade:"data:image/jpeg;base64,",
    asphalt: 'data:image/jpeg;base64,',
    wall:"data:image/jpeg;base64,",
    mountains: "data:image/jpeg;base64,",
    harborSky: "data:image/jpeg;base64,",
    harborMetal: "data:image/jpeg;base64,"
  });
})(window);
